3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.Collection;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Detects owners that share a household, i.e. have the same last name and address
11	 * (compared case-insensitively with collapsed whitespace).
12	 */
13	final class HouseholdDuplicates {
14	
15	    private HouseholdDuplicates() {
16	    }
17	
18	    /**
19	     * Returns {@code true} when an existing owner shares {@code candidate}'s household and the
20	     * request did not opt in via {@code sharesHousehold}.
21	     */
22	    static boolean isRejectedDuplicate(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
23	        if (Boolean.TRUE.equals(sharesHousehold)) {
24	            return false;
25	        }
26	        String key = key(candidate);
27	        return existing.stream().anyMatch(other -> key(other).equals(key));
28	    }
29	
30	    /**
31	     * When {@code candidate} opted in via {@code sharesHousehold} and joins an existing owner's
32	     * household (same last name and address), stamps it with the household's stable shared id.
33	     */
34	    static void assignHousehold(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
35	        if (!Boolean.TRUE.equals(sharesHousehold)) {
36	            return;
37	        }
38	        String key = key(candidate);
39	        if (existing.stream().anyMatch(other -> key(other).equals(key))) {
40	            candidate.setHouseholdId(householdId(key));
41	        }
42	    }
43	
44	    private static String householdId(String key) {
45	        try {
46	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
47	            StringBuilder sb = new StringBuilder();
48	            for (int i = 0; i < 8; i++) {
49	                sb.append(String.format("%02x", digest[i]));
50	            }
51	            return sb.toString();
52	        }
53	        catch (Exception e) {
54	            throw new IllegalStateException(e);
55	        }
56	    }
57	
58	    private static String key(Owner owner) {
59	        return norm(owner.getLastName()) + "\n" + norm(owner.getAddress());
60	    }
61	
62	    private static String norm(String value) {
63	        return value == null ? "" : value.replaceAll("\\s+", " ").trim().toLowerCase();
64	    }
65	}
